import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';

declare const __AXO_CLI__: string | undefined;

/**
 * Knock hook: Claude Code PreToolUse hook for Write|Edit|MultiEdit|NotebookEdit. Plain sh + curl,
 * so no Node startup per file write. Forwards the hook payload (stdin) to the node, which decides.
 * Fails open: if the node can't be reached the write is allowed and a line is logged.
 */
export const KNOCK_SH = `#!/bin/sh
# Axo knock hook (generated by axo-node; overwritten on node start).
[ -n "$AXO_NODE_URL" ] && [ -n "$AXO_TOKEN" ] || exit 0
out=$(curl -sS -m 4 -X POST \\
  -H "Authorization: Bearer $AXO_TOKEN" -H 'Content-Type: application/json' \\
  --data-binary @- "$AXO_NODE_URL/api/knock?format=text" 2>&1)
if [ $? -ne 0 ]; then
  log="$(dirname "$0")/../logs/knock.log"
  if [ -f "$log" ] && [ "$(wc -c < "$log")" -gt 1048576 ]; then : > "$log"; fi
  echo "$(date -u +%FT%TZ) $AXO_AGENT_ID fail-open: $out" >> "$log" 2>/dev/null
  exit 0
fi
case "$out" in
  DENY*) printf '%s\\n' "\${out#DENY }" >&2; exit 2 ;;
esac
exit 0
`;

export interface BinPaths { dir: string; axo: string; knock: string; cli: string }

/** Settings JSON passed to every claude process via `--settings` (identity comes from env). */
export function knockSettings(knockPath: string): string {
  return JSON.stringify({
    hooks: {
      PreToolUse: [{
        matcher: 'Write|Edit|MultiEdit|NotebookEdit',
        hooks: [{ type: 'command', command: shq(knockPath), timeout: 10 }], // executable (0755); bare path keeps Claude's 'hook error: [cmd]' prefix short
      }],
    },
  });
}

/**
 * Write `<home>/bin/{knock.sh, axo, axo.mjs}`. The runtime puts `<home>/bin` first on each agent's
 * PATH. In the bundled node the CLI source is embedded at build time; from source we point the
 * wrapper at packages/cli/src/axo.ts (Node runs TypeScript natively).
 */
export function installBin(home: string): BinPaths {
  const dir = join(home, 'bin');
  mkdirSync(dir, { recursive: true });
  const knock = join(dir, 'knock.sh');
  writeIfChanged(knock, KNOCK_SH, 0o755);

  let cli: string;
  if (typeof __AXO_CLI__ === 'string') {
    cli = join(dir, 'axo.mjs');
    writeIfChanged(cli, __AXO_CLI__, 0o644);
  } else {
    cli = fileURLToPath(new URL('../../../cli/src/axo.ts', import.meta.url));
  }
  const axo = join(dir, 'axo');
  writeIfChanged(axo, `#!/bin/sh\nELECTRON_RUN_AS_NODE=1 exec ${shq(process.execPath)} --disable-warning=ExperimentalWarning ${shq(cli)} "$@"\n`, 0o755);
  return { dir, axo, knock, cli };
}

function writeIfChanged(path: string, content: string, mode: number): void {
  if (!existsSync(path) || readFileSync(path, 'utf8') !== content) writeFileSync(path, content);
  chmodSync(path, mode);
}

export function shq(s: string): string {
  return `'${s.replace(/'/g, `'\\''`)}'`;
}
